/* ── Chapter 14–16 quiz generators ───────────────────────────── */
/* choices de-duplicated on the formatted string; fallbacks are multiples of the correct value */
function strChoices(correct, wrongs, fmt) {
  var seen = {}, out = [], i, c = fmt(correct), fb = [1.25, 0.8, 1.5, 0.5, 2, 0.25, 3];
  seen[c] = true; out.push(c);
  for (i = 0; i < wrongs.length && out.length < 4; i++) { var w = fmt(wrongs[i]); if (!seen[w]) { seen[w] = true; out.push(w); } }
  for (i = 0; i < fb.length && out.length < 4; i++) { var f = fmt(correct === 0 ? fb[i] : correct * fb[i]); if (!seen[f]) { seen[f] = true; out.push(f); } }
  return out;
}
function fmtShares(v) { var r = Math.round(v); return (r < 0 ? "Sell " : "Buy ") + fdInt(Math.abs(r)) + " shares"; }
function fmtInt0(v) { var r = Math.round(v); return (r < 0 ? "−" : "") + fdInt(Math.abs(r)); }
function fmtD3(v) { var r = Math.round(v * 1000) / 1000; return (r < 0 ? "−" : "") + Math.abs(r).toFixed(3); }
function fmtUsd2s(v) { var r = Math.round(v * 100) / 100; return (r < 0 ? "−$" : "$") + Math.abs(r).toFixed(2); }
function fmtGain0(v) { var r = Math.round(v); if (r === 0) { return "No change"; } return (r > 0 ? "A gain of " : "A loss of ") + fdMoney(Math.abs(r)); }

